require "json"
toolctx = Class.new { include ToolsHelper; include Rails.application.routes.url_helpers }.new
TOOLS = toolctx.tools_registry
TEMPLATES = TemplatesController::TEMPLATES

def tool_hits(q)
  tv = SearchQueryParser.tokens(q)
  return [] if tv.empty?
  TOOLS.select { |t|
    hay = [t[:title], t[:desc], t[:category], t[:domain], t[:keywords]].compact.join(" ").downcase
    tv.all? { |vs| vs.any? { |v| hay.include?(v.downcase) } }
  }.first(4)
end
def tmpl_hits(q)
  qq = q.downcase
  TEMPLATES.select { |t| t[:title].downcase.include?(qq) || t[:desc].downcase.include?(qq) || t[:category].downcase.include?(qq) }.first(3)
end

linked = ContentAuthorityLink.where(content_type: "Topic").distinct.pluck(:content_id).compact.to_set

rows = []
QUERIES.each do |q, meta|
  topics = Topic.search_multiple(q, limit: 6).to_a
  audits = AuditCase.search_by_query(q, limit: 5).to_a
  guides = Guide.published.search_by_keyword(q).limit(5).to_a
  tmpls  = tmpl_hits(q)
  tools  = tool_hits(q)
  answer = Topic.answer_for(q, topics)

  top = topics.first
  howto_n   = topics.sum { |t| (t.howto_steps.is_a?(Array) ? t.howto_steps.size : 0) }
  flow_n    = topics.count { |t| t.flowchart_mermaid.present? || t.flowchart_url.present? }
  tips_n    = topics.count { |t| t.practical_tips.present? }
  law_n     = topics.count { |t| t.law_content.present? }
  interp_n  = topics.count { |t| t.interpretation_content.present? }
  authlink_n= topics.count { |t| linked.include?(t.id) }

  total = topics.size + audits.size + guides.size + tmpls.size + tools.size

  rows << {
    q: q, origin: meta["origin"], n: meta["n"],
    topic: topics.size, guide: guides.size, audit: audits.size, tmpl: tmpls.size, tool: tools.size,
    total: total,
    top_slug: top&.slug, top_cat: top&.category,
    answer: answer ? { question: answer[:question], topic: answer[:topic].slug, hits: answer[:hits] } : nil,
    howto: howto_n, flow: flow_n, tips: tips_n, law: law_n, interp: interp_n, authlink: authlink_n,
    audit_slugs: audits.first(3).map(&:slug), guide_slugs: guides.first(3).map(&:slug),
    tool_titles: tools.map { |t| t[:title] }
  }
end
puts JSON.generate({ measured_at: Time.current.iso8601, rev: ENV["KAMAL_VERSION"], rows: rows })
